,{"table_name":"terminal_tokens","name":"location_id","collation":"$DATABASE_DEFAULT"},{"table_name":"terminal_tokens","name":"location_name","collation":"$DATABASE_DEFAULT"},{"table_name":"terminal_tokens","name":"management_registration","collation":null},{"table_name":"terminal_tokens","name":"management_sync_enabled","collation":null},{"table_name":"terminal_tokens","name":"management_sync_proof_hash","collation":"$DATABASE_DEFAULT"},{"table_name":"terminal_tokens","name":"platform","collation":"$DATABASE_DEFAULT"},{"table_name":"terminal_tokens","name":"reissued_at","collation":null},{"table_name":"terminal_tokens","name":"replaced_by","collation":null},{"table_name":"terminal_tokens","name":"revoked_at","collation":null},{"table_name":"terminal_tokens","name":"row_version","collation":null},{"table_name":"terminal_tokens","name":"status","collation":"$DATABASE_DEFAULT"},{"table_name":"uom_units","name":"allow_decimal","collation":null},{"table_name":"uom_units","name":"code","collation":"$DATABASE_DEFAULT"},{"table_name":"uom_units","name":"created_at","collation":null},{"table_name":"uom_units","name":"deleted_at","collation":"$DATABASE_DEFAULT"},{"table_name":"uom_units","name":"id","collation":null},{"table_name":"uom_units","name":"is_active","collation":null},{"table_name":"uom_units","name":"name","collation":"$DATABASE_DEFAULT"},{"table_name":"uom_units","name":"row_version","collation":null},{"table_name":"uom_units","name":"sort","collation":null},{"table_name":"uom_units","name":"updated_at","collation":null},{"table_name":"user_roles","name":"created_at","collation":null},{"table_name":"user_roles","name":"id","collation":null},{"table_name":"user_roles","name":"role","collation":"$DATABASE_DEFAULT"},{"table_name":"user_roles","name":"user_id","collation":null},{"table_name":"whatsapp_queue","name":"body","collation":"$DATABASE_DEFAULT"},{"table_name":"whatsapp_queue","name":"created_at","collation":null},{"table_name":"whatsapp_queue","name":"error