SET @fingerprint=CONVERT(varchar(64),HASHBYTES(''''SHA2_256'''',CONVERT(varbinary(max),CASE WHEN EXISTS(SELECT 1 FROM (SELECT t.name table_name,o.type,CONVERT(int,t.is_memory_optimized) memory_optimized,t.temporal_type,CASE WHEN ct.object_id IS NULL THEN 0 ELSE 1 END tracked,CONVERT(int,ct.is_track_columns_updated_on) track_columns FROM sys.tables t JOIN sys.objects o ON o.object_id=t.object_id LEFT JOIN sys.change_tracking_tables ct ON ct.object_id=t.object_id WHERE t.schema_id=SCHEMA_ID(N''''dbo'''') AND t.name IN(N''''activity_events'''',N''''app_users'''',N''''audit_logs'''',N''''authorization_action_history'''',N''''authorization_actions'''',N''''authorization_log'''',N''''authorization_requests'''',N''''booking_payments'''',N''''bookings'''',N''''branch_telemetry'''',N''''cashiers'''',N''''change_history'''',N''''coupon_campaigns'''',N''''coupon_events'''',N''''drawer_events'''',N''''entity_status_history'''',N''''held_orders'''',N''''integration_settings'''',N''''issued_vouchers'''',N''''item_activity_logs'''',N''''local_operation_receipts'''',N''''member_verifications'''',N''''members'''',N''''membership_tiers'''',N''''nav_pins'''',N''''offline_sync_audit_log'''',N''''payment_transactions'''',N''''payment_types'''',N''''pin_attempts'''',N''''pos_document_counters'''',N''''pos_jobs'''',N''''pos_schema_migrations'''',N''''pos_settings'''',N''''pos_store_settings'''',N''''pos_sync_shift_author_keys'''',N''''pos_sync_shift_authors'''',N''''pos_sync_shift_baselines'''',N''''pos_sync_shift_closing_starts'''',N''''pos_sync_shift_intent_starts'''',N''''pos_sync_shift_intents'''',N''''pos_sync_shift_openings'''',N''''product_barcodes'''',N''''product_categories'''',N''''products'''',N''''promotions'''',N''''public_flags'''',N''''purchase_order_items'''',N''''purchase_orders'''',N''''record_edits'''',N''''sale_items'''',N''''sales'''',N''''secure_settings'''',N''''security_findings'''',N''''settings_locks'''',N''''settings_overrides'''',N''''settings_scoped'''',N''''shift_cash_counts'''',N''''shift_close_events'''',N''''shift_notifications'''',N''''shift_reconciliations'''',N''''shift_sessions'''',N''''shift_variance_alerts'''',N''''shifts'''',N''''sku_audit'''',N''''staff_roles'''',N''''stock_adjustments'''',N''''stock_count_drafts'''',N''''stock_delta_applied'''',N''''stock_transfer_items'''',N''''stock_transfers'''',N''''store_groups'''',N''''stores'''',N''''suppliers'''',N''''sync_change_journal'''',N''''sync_checkpoints'''',N''''sync_conflicts'''',N''''sync_metadata'''',N''''system_audit_logs'''',N''''terminal_commands'''',N''''terminal_recovery_secrets'''',N''''terminal_tokens'''',N''''uom_units'''',N''''user_roles'''',N''''whatsapp_queue'''')) nonempty_shape) THEN (SELECT CONVERT(nvarchar(max),current_shape.[table_name]) AS [table_name],CONVERT(nvarchar(max),current_shape.[type]) AS [type],CONVERT(int,current_shape.[memory_optimized]) AS [memory_optimized],CONVERT(int,current_shape.[temporal_type]) AS [temporal_type],CONVERT(int,current_shape.[tracked]) AS [tracked],CONVERT(int,current_shape.[track_columns]) AS [track_columns] FROM (SELECT t.name table_name,o.type,CONVERT(int,t.is_memory_optimized) memory_optimized,t.temporal_type,CASE WHEN ct.object_id IS NULL THEN 0 ELSE 1 END tracked,CONVERT(int,ct.is_track_columns_updated_on) track_columns FROM sys.tables t JOIN sys.objects o ON o.object_id=t.object_id LEFT JOIN sys.change_tracking_tables ct ON ct.object_id=t.object_id WHERE t.schema_id=SCHEMA_ID(N''''dbo'''') AND t.name IN(N''''activity_events'''',N''''app_users'''',N''''audit_logs'''',N''''authorization_action_history'''',N''''authorization_actions'''',N''''authorization_log'''',N''''authorization_requests'''',N''''booking_payments'''',N''''bookings'''',N''''branch_telemetry'''',N''''cashiers'''',N''''change_history'''',N''''coupon_campaigns'''',N''''coupon_events'''',N''''drawer_events'''',N''''entity_status_history'''',N''''held_orders'''',N''''integration_settings'''',N''''issued_vouchers'''',N''''item_activity_l